package com.codeguardian.service.rag; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*; @Repository public class PgVectorKnowledgeStore{private final JdbcTemplate jdbc;private final EmbeddingService embeddings;public PgVectorKnowledgeStore(JdbcTemplate jdbc,EmbeddingService embeddings){this.jdbc=jdbc;this.embeddings=embeddings;}public void save(Long fileId,String content){jdbc.update("insert into knowledge_embeddings(knowledge_file_id,content,embedding) values(?,?,cast(? as vector))",fileId,content,embeddings.asPgVector(embeddings.embed(content)));}public List<String> search(String query,int limit){String vector=embeddings.asPgVector(embeddings.embed(query));return jdbc.queryForList("select content from knowledge_embeddings order by embedding <=> cast(? as vector) limit ?",String.class,vector,limit);}}
